config_schema_snippet:
{
  "sla": {
    "committed_throughput": 1200,            // tokens/sec (customer commitment)
    "p95_latency_ms": 250,                  // p95 latency budget
    "burst_window_sec": 30,                 // allowed burst duration
    "burst_multiplier": 2.5                 // burst headroom relative to committed throughput
  },
  "translator": {
    "target_metrics": ["tokens_per_sec", "target_concurrency", "p95_latency_ms"],
    "mapping_strategy": "multi-objective"
  },
  "safety_throttles": {
    "max_overcommit_pct": 25,                // hard cap over commitment
    "headroom_credits": 300,                // token-budget to allow transient bursts
    "cooldown_seconds": 120,
    "fallback_policy": "queue_then_reject"
  }
}
